import{_ as s,o as a,c as t,ah as n}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Changements de classe","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/secretariat/changements-de-classe.md","filePath":"src/guide/secretariat/changements-de-classe.md"}'),l={name:"guide/secretariat/changements-de-classe.md"};function r(i,e,o,u,c,d){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="changements-de-classe" tabindex="-1">Changements de classe <a class="header-anchor" href="#changements-de-classe" aria-label="Permalink to &quot;Changements de classe&quot;">​</a></h1><p>Il arrive qu&#39;un élève doive changer de classe après avoir été placé : un changement d&#39;orientation dans les premières semaines (de 1ère C en 1ère D, par exemple), ou une correction avant que les listes de classe ne soient arrêtées. La page <strong>Changements de classe</strong>, dans l&#39;espace <strong>Élèves et admissions</strong>, sert à cela. Elle est ouverte au secrétariat et à l&#39;administration.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Un changement de classe se fait <strong>sur le même site</strong> et <strong>dans la même année scolaire</strong>. Pour faire passer un élève sur un autre site, utilisez un <a href="/era-guide/guide/secretariat/transferts-sites.html">transfert de site</a>.</p></div><h2 id="changer-un-eleve-de-classe" tabindex="-1">Changer un élève de classe <a class="header-anchor" href="#changer-un-eleve-de-classe" aria-label="Permalink to &quot;Changer un élève de classe&quot;">​</a></h2><ol><li>Dans <strong>Élève</strong>, tapez au moins deux lettres de son nom ou de son prénom, puis cliquez sur l&#39;élève dans la liste. Seuls les élèves inscrits sur une année en cours (ou déjà préparée) apparaissent.</li><li>Vérifiez sa <strong>classe actuelle</strong>, affichée avec son département, son site et l&#39;année. Si ce n&#39;est pas le bon élève, cliquez sur <strong>Choisir un autre élève</strong>.</li><li>Dans <strong>Nouvelle classe</strong>, choisissez la classe d&#39;arrivée. La liste ne propose que les classes du même site et de la même année, avec leur effectif et leur capacité.</li><li>Indiquez un <strong>Motif</strong>, par exemple « réorientation en série D ». Il est facultatif, sauf si la classe est pleine, et reste visible dans l&#39;historique.</li><li>Cliquez sur <strong>Changer de classe</strong>.</li></ol><p>L&#39;inscription de l&#39;élève est déplacée, pas recréée : ses paiements, son échéancier et ses bulletins restent rattachés à son dossier.</p><h2 id="plusieurs-eleves" tabindex="-1">Plusieurs élèves à la fois <a class="header-anchor" href="#plusieurs-eleves" aria-label="Permalink to &quot;Plusieurs élèves à la fois {#plusieurs-eleves}&quot;">​</a></h2><p>Pour réorganiser les listes, le bouton <strong>Changer plusieurs élèves de classe</strong> déplace un groupe d&#39;élèves d&#39;un coup.</p><ol><li>Choisissez la <strong>Classe de départ</strong> : ses élèves s&#39;affichent, avec le nombre de notes qu&#39;un déplacement abandonnerait.</li><li>Cochez les élèves à déplacer (<strong>Tout cocher</strong> les prend tous).</li><li>Choisissez la <strong>Classe d&#39;arrivée</strong> (même année, même site), puis, si besoin, le motif.</li><li>Cliquez sur <strong>Déplacer N élèves</strong>.</li></ol><p>Les règles sont celles d&#39;un changement individuel. Le déplacement est <strong>tout ou rien</strong> : si un élève ne peut pas être déplacé, le message le nomme et personne ne bouge. Si la classe d&#39;arrivée n&#39;a pas assez de places, il faut cocher « Placer les élèves dans cette classe malgré tout » et donner un motif : chaque dépassement est enregistré. Chaque élève garde sa ligne dans l&#39;historique.</p><h2 id="les-avertissements-avant-de-valider" tabindex="-1">Les avertissements avant de valider <a class="header-anchor" href="#les-avertissements-avant-de-valider" aria-label="Permalink to &quot;Les avertissements avant de valider&quot;">​</a></h2><p>Selon la situation, un encadré apparaît sous la classe choisie :</p><ul><li><strong>Des notes ont déjà été saisies</strong> dans la classe d&#39;origine : elles ne sont pas reportées et ne comptent plus pour l&#39;élève. Elles ne sont pas effacées pour autant, et le nombre de notes abandonnées reste inscrit dans l&#39;historique.</li><li><strong>La classe appartient à un autre département</strong> : vérifiez les options de l&#39;élève. Sa grille de frais peut être différente : ses services optionnels (cantine, transport…) passent sur la nouvelle grille, repris s&#39;ils y existent (même type, même libellé) au tarif de cette grille, retirés sinon. Un service déjà payé reste marqué payé.</li><li><strong>La classe a atteint sa capacité</strong> : le bouton reste inactif tant que vous n&#39;avez pas coché <strong>Placer l&#39;élève dans cette classe malgré tout</strong> et écrit le <strong>Motif</strong>, obligatoire dans ce cas. Comme pour une admission ou une mobilité, le dépassement est enregistré, la direction du site en est informée, et il apparaît dans le <a href="/era-guide/guide/direction/pilotage.html#classes-en-sureffectif">Pilotage</a>.</li></ul><h2 id="quand-le-changement-est-refuse" tabindex="-1">Quand le changement est refusé <a class="header-anchor" href="#quand-le-changement-est-refuse" aria-label="Permalink to &quot;Quand le changement est refusé&quot;">​</a></h2><ul><li>La classe choisie est celle où se trouve déjà l&#39;élève.</li><li>L&#39;<strong>année scolaire est clôturée</strong> : plus aucun changement n&#39;y est possible (voir la clôture d&#39;année dans le guide de l&#39;administrateur).</li></ul><h2 id="l-historique" tabindex="-1">L&#39;historique <a class="header-anchor" href="#l-historique" aria-label="Permalink to &quot;L&#39;historique&quot;">​</a></h2><p>Sous le formulaire, l&#39;<strong>Historique des changements</strong> liste chaque changement : la date, l&#39;élève, la classe de départ et d&#39;arrivée avec l&#39;année, le motif et la personne qui l&#39;a fait. Le nombre de notes abandonnées y figure quand il y en avait. Les <a href="/era-guide/guide/secretariat/transferts-sites.html">transferts de site</a> y figurent aussi, marqués « Changement de site », avec le motif donné dans la demande.</p>',17)])])}const m=s(l,[["render",r]]);export{g as __pageData,m as default};
